function main(): void {
  const log: string[] = [];
  const key = (label: string): string => { log.push('key ' + label); return label; };
  const tick = (label: string): number => { log.push('val ' + label); return log.length; };
  const o: any = Object.defineProperties({}, {
    [key('a')]: { value: tick('a'), enumerable: true, writable: true, configurable: true },
    [key('b')]: { value: tick('b'), enumerable: true, writable: true, configurable: true },
    c: { value: tick('c'), enumerable: true, writable: true, configurable: true },
  });
  console.log(log.join('|'));
  console.log(o.a, o.b, o.c, Object.keys(o).join());
}
